import{c as o,Q as e,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Probing, Fusion, and Trustworthiness: A Systematic Evaluation of Foundation Model Representations for Multimodal Cancer Analysis","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.17115","title":"Probing, Fusion, and Trustworthiness: A Systematic Evaluation of Foundation Model Representations for Multimodal Cancer Analysis","archived_date":"2026-07-23T00:00:00.000Z","arxiv_id":2606.17115,"authors":["Jingyu Hu","Giuseppe Tripodi","Reed Naidoo","Sarah F. McGough","Tapabrata Chakraborti"],"domain":"genomic-biological-foundation-models","published_date":"2026-06-15T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-23-cancer-foundation-model-trustworthiness-2606-17115.md","filePath":"research/papers/2026-07-23-cancer-foundation-model-trustworthiness-2606-17115.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-07-23-cancer-foundation-model-trustworthiness-2606-17115.md"};function i(r,a,d,l,u,c){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="probing-fusion-and-trustworthiness-a-systematic-evaluation-of-foundation-model-representations-for-multimodal-cancer-analysis" tabindex="-1">Probing, Fusion, and Trustworthiness: A Systematic Evaluation of Foundation Model Representations for Multimodal Cancer Analysis <a class="header-anchor" href="#probing-fusion-and-trustworthiness-a-systematic-evaluation-of-foundation-model-representations-for-multimodal-cancer-analysis" aria-label="Permalink to &quot;Probing, Fusion, and Trustworthiness: A Systematic Evaluation of Foundation Model Representations for Multimodal Cancer Analysis&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文系統性評測基礎模型在多模態癌症分析任務中的表徵品質，融合全切片病理影像（whole-slide images, WSI）與轉錄體（transcriptomic）資料。核心貢獻分三層：(1) probing——凍結表徵在下游癌症分類/預後任務上的可分性；(2) fusion——不同模態表徵的融合策略對表現的邊際貢獻；(3) trustworthiness——模型輸出在分布外（out-of-distribution）樣本與臨床決策情境下的可信度評估。論文指出多模態融合雖能提升平均表現，但可信度（校準度、對抗性穩健度）並未隨之同步提升，形成「表現提升 vs 可信度落後」的落差，呼應醫療 AI 部署的核心痛點。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>多模態病理/癌症基礎模型的可信度評測，在 workspace 既有題庫（daily-topics/weekly-focus/papers）與 NEW-DOMAINS 既探勘領域紀錄中關鍵詞命中皆為 0，屬完全未觸及的生物醫療 AI 子領域。</p>',5)])])}const m=o(s,[["render",i]]);export{h as __pageData,m as default};
